RY_TO_TIMESTAMP(DATETIME, \'MM-DD-YYYY HH24:MI:SS\') ) AS DATE) ORDER BY COALESCE( TRY_TO_TIMESTAMP(DATETIME, \'MM/DD/YYYY HH24:MI:SS\'), TRY_TO_TIMESTAMP(DATETIME, \'MM-DD-YYYY HH24:MI:SS\') ) DESC ) AS rn FROM snitch_db.maplemonk.snitch_db_get_store_count ) a LEFT JOIN snitch_db.maplemonk.delopt_mapping b ON UPPER(a.store_code) = UPPER(b.store_name) WHERE a.rn = 1 ), metricss AS ( SELECT * FROM snitch_db.maplemonk.Offline_Detailed_Summary_V2 ) SELECT s.STORE_CODE, s.CODE, s.date_cast AS store_date, CURRENT_DATE AS Current_date_mapped, s.Walk_ins, o.order_dt AS order_date, o.marketplace_mapped, o.Orders, o.QTY, B.TODAY_SALES, B.TARGET, B.MTD_SALES, B.MTD, B.BILLS, B.MULTIES, B.QTY AS QTYSS, B.ATV, B.UPT, B.ASP, B.AM, B.STATE FROM Stores s LEFT JOIN Orders o ON s.CODE = o.BRANCH_CODE AND s.date_cast = o.order_dt LEFT JOIN metricss B ON s.CODE = B.BRANCH_CODE AND s.date_cast = B.DATE WHERE s.CODE IS NOT NULL;",
